/**
 * `npm run content:graph`: writes one Mermaid flowchart per chapter to `docs/graphs/<chapter>.md`
 * so the team can review story trees visually.
 */
import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { ContentLoader, chapterToMermaid } from '@commander/engine';
import { readContentFiles, repoRoot } from './lib/read-content.js';

const outDir = join(repoRoot, 'docs', 'graphs');
mkdirSync(outDir, { recursive: true });
const { data } = ContentLoader.load(readContentFiles());
const index: string[] = [
  '# Story graphs',
  '',
  'Generated by `npm run content:graph`. Do not edit by hand.',
  '',
];
for (const [id, chapter] of Object.entries(data.chapters)) {
  writeFileSync(join(outDir, `${id}.md`), chapterToMermaid(chapter));
  index.push(`- [${chapter.def.title}](./${id}.md) (\`${id}\`, ${chapter.nodes.length} nodes)`);
}
writeFileSync(join(outDir, 'README.md'), `${index.join('\n')}\n`);
console.log(`Wrote ${Object.keys(data.chapters).length} chapter graphs to docs/graphs/`);
